from sqlalchemy import Boolean, Column, Date, ForeignKey, Integer, Numeric, String, TIMESTAMP, Text, UniqueConstraint
from sqlalchemy.sql import func
from app.database.base import Base
class Supplier(Base):
    __tablename__="suppliers"
    id=Column(Integer,primary_key=True); tenant_id=Column(Integer,ForeignKey("tenants.id",ondelete="CASCADE"),nullable=False,index=True); code=Column(String(80),nullable=False); name=Column(String(200),nullable=False); phone=Column(String(80)); email=Column(String(200)); tax_id=Column(String(100)); address=Column(Text); credit_limit=Column(Numeric(18,2),nullable=False,default=0,server_default="0"); is_active=Column(Boolean,nullable=False,default=True,server_default="true"); created_at=Column(TIMESTAMP(timezone=True),server_default=func.now(),nullable=False); updated_at=Column(TIMESTAMP(timezone=True),server_default=func.now(),onupdate=func.now(),nullable=False)
    __table_args__=(UniqueConstraint("tenant_id","code",name="uq_suppliers_tenant_code"),)
class PurchaseOrder(Base):
    __tablename__="purchase_orders"
    id=Column(Integer,primary_key=True); tenant_id=Column(Integer,ForeignKey("tenants.id",ondelete="CASCADE"),nullable=False,index=True); company_id=Column(Integer,ForeignKey("companies.id",ondelete="RESTRICT"),nullable=False,index=True); branch_id=Column(Integer,ForeignKey("branches.id",ondelete="RESTRICT"),nullable=False,index=True); supplier_id=Column(Integer,ForeignKey("suppliers.id",ondelete="RESTRICT"),nullable=False,index=True); order_number=Column(String(80),nullable=False); order_date=Column(Date,nullable=False); status=Column(String(30),nullable=False,default="draft",server_default="draft",index=True); subtotal=Column(Numeric(18,2),nullable=False,default=0,server_default="0"); discount=Column(Numeric(18,2),nullable=False,default=0,server_default="0"); tax=Column(Numeric(18,2),nullable=False,default=0,server_default="0"); grand_total=Column(Numeric(18,2),nullable=False,default=0,server_default="0"); notes=Column(Text); created_at=Column(TIMESTAMP(timezone=True),server_default=func.now(),nullable=False); updated_at=Column(TIMESTAMP(timezone=True),server_default=func.now(),onupdate=func.now(),nullable=False)
    __table_args__=(UniqueConstraint("tenant_id","order_number",name="uq_purchase_orders_tenant_number"),)
class PurchaseOrderLine(Base):
    __tablename__="purchase_order_lines"
    id=Column(Integer,primary_key=True); purchase_order_id=Column(Integer,ForeignKey("purchase_orders.id",ondelete="CASCADE"),nullable=False,index=True); product_id=Column(Integer,ForeignKey("products.id",ondelete="RESTRICT"),nullable=False,index=True); quantity=Column(Numeric(18,6),nullable=False); unit_price=Column(Numeric(18,2),nullable=False); discount=Column(Numeric(18,2),nullable=False,default=0,server_default="0"); tax_rate=Column(Numeric(8,4),nullable=False,default=0,server_default="0"); line_total=Column(Numeric(18,2),nullable=False)
class PurchaseReceipt(Base):
    __tablename__="purchase_receipts"
    id=Column(Integer,primary_key=True); tenant_id=Column(Integer,ForeignKey("tenants.id",ondelete="CASCADE"),nullable=False,index=True); purchase_order_id=Column(Integer,ForeignKey("purchase_orders.id",ondelete="RESTRICT"),nullable=False,index=True); warehouse_id=Column(Integer,ForeignKey("warehouses.id",ondelete="RESTRICT"),nullable=False,index=True); receipt_number=Column(String(80),nullable=False); receipt_date=Column(Date,nullable=False); status=Column(String(30),nullable=False,default="posted",server_default="posted"); notes=Column(Text); created_at=Column(TIMESTAMP(timezone=True),server_default=func.now(),nullable=False)
    __table_args__=(UniqueConstraint("tenant_id","receipt_number",name="uq_purchase_receipts_tenant_number"),)
class PurchaseReceiptLine(Base):
    __tablename__="purchase_receipt_lines"
    id=Column(Integer,primary_key=True); receipt_id=Column(Integer,ForeignKey("purchase_receipts.id",ondelete="CASCADE"),nullable=False,index=True); product_id=Column(Integer,ForeignKey("products.id",ondelete="RESTRICT"),nullable=False,index=True); location_id=Column(Integer,ForeignKey("warehouse_locations.id",ondelete="RESTRICT"),nullable=False,index=True); quantity=Column(Numeric(18,6),nullable=False)
class PurchaseInvoice(Base):
    __tablename__="purchase_invoices"
    id=Column(Integer,primary_key=True); tenant_id=Column(Integer,ForeignKey("tenants.id",ondelete="CASCADE"),nullable=False,index=True); company_id=Column(Integer,ForeignKey("companies.id",ondelete="RESTRICT"),nullable=False,index=True); branch_id=Column(Integer,ForeignKey("branches.id",ondelete="RESTRICT"),nullable=False,index=True); supplier_id=Column(Integer,ForeignKey("suppliers.id",ondelete="RESTRICT"),nullable=False,index=True); purchase_order_id=Column(Integer,ForeignKey("purchase_orders.id",ondelete="RESTRICT"),nullable=True,index=True); invoice_number=Column(String(80),nullable=False); invoice_date=Column(Date,nullable=False); status=Column(String(30),nullable=False,default="draft",server_default="draft",index=True); subtotal=Column(Numeric(18,2),nullable=False,default=0,server_default="0"); discount=Column(Numeric(18,2),nullable=False,default=0,server_default="0"); tax=Column(Numeric(18,2),nullable=False,default=0,server_default="0"); grand_total=Column(Numeric(18,2),nullable=False,default=0,server_default="0"); journal_entry_id=Column(Integer,ForeignKey("journal_entries.id",ondelete="SET NULL"),nullable=True,index=True); created_at=Column(TIMESTAMP(timezone=True),server_default=func.now(),nullable=False)
class PurchaseInvoiceLine(Base):
    __tablename__="purchase_invoice_lines"
    id=Column(Integer,primary_key=True); purchase_invoice_id=Column(Integer,ForeignKey("purchase_invoices.id",ondelete="CASCADE"),nullable=False,index=True); product_id=Column(Integer,ForeignKey("products.id",ondelete="RESTRICT"),nullable=False,index=True); quantity=Column(Numeric(18,6),nullable=False); unit_price=Column(Numeric(18,2),nullable=False); discount=Column(Numeric(18,2),nullable=False,default=0,server_default="0"); tax_rate=Column(Numeric(8,4),nullable=False,default=0,server_default="0"); line_total=Column(Numeric(18,2),nullable=False)
